import sys

data = sys.stdin.read().split()
n = int(data[0])
cost = [int(x) for x in data[1:1 + n]]
feat = data[1 + n:1 + 2 * n]
INF = float('inf')
best = [INF] * (n + 1)
for mask in range(1 << n):
    a = b = tot = 0
    for i in range(n):
        if mask >> i & 1:
            tot += cost[i]
            if feat[i][0] == '1':
                a += 1
            if feat[i][1] == '1':
                b += 1
    c = min(a, b)
    for k in range(1, c + 1):
        if tot < best[k]:
            best[k] = tot
print(' '.join(str(best[k]) if best[k] != INF else '-1' for k in range(1, n + 1)))

